  console.log('localStorage:', JSON.stringify(ls), '(expected null)');
  console.log('sees cookie :', ck, '(expected false)');
  const leaked = ls === 'from_default' || ck === true;
  console.log(leaked ? 'FAIL — storage leaks' : 'PASS — isolated');
  for (const p of [def, isoP]) { try { orca(['tab','close','--page',p]); } catch {} }
  try { orca(['tab','profile','delete','--profile',iso]); } catch {}
  process.exit(leaked ? 1 : 0);
})();
